class Solution {
  private static boolean isPrime(long x) {
    if (x < 2) return false;
    for (long d = 2; d * d <= x; d++) if (x % d == 0) return false;
    return true;
  }

  public boolean completePrime(int num) {
    String s = Integer.toString(num);
    for (int i = 1; i <= s.length(); i++) {
      if (!isPrime(Long.parseLong(s.substring(0, i)))) return false;
      if (!isPrime(Long.parseLong(s.substring(s.length() - i)))) return false;
    }
    return true;
  }
}
